using FluentAssertions;
using MessagePack;

namespace Receipts.GeneratedTests;

public class MessagePackSecurityCopyTests
{
    [Fact]
    public void UntrustedData_WithMaximumObjectGraphDepth_KeepsHashCollisionResistance()
    {
        MessagePackSecurity.UntrustedData.HashCollisionResistant.Should().BeTrue();

        MessagePackSecurity derived = MessagePackSecurity.UntrustedData.WithMaximumObjectGraphDepth(100);

        derived.MaximumObjectGraphDepth.Should().Be(100);
        derived.HashCollisionResistant.Should().BeTrue("deriving a security setting from UntrustedData must not silently drop collision-resistant hashing");
    }
}
